import{_ as r,l as i,o as e,c,v as t,p as n,x as o,d as l,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"伪共享","description":"","frontmatter":{"title":"伪共享","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/false-sharing.md","filePath":"cs/false-sharing.md","lastUpdated":1789023840000}'),h={name:"cs/false-sharing.md"};function f(E,a,_,m,A,u){const s=i("Mermaid");return e(),c("div",null,[a[1]||(a[1]=t('<h1 id="伪共享" tabindex="-1">伪共享 <a class="header-anchor" href="#伪共享" aria-label="Permalink to &quot;伪共享&quot;">​</a></h1><div class="epigraph"><p>两个核写的是不同变量，只要落在同一 cache 行，协议仍按真共享来回作废；程序员看见的是无锁计数器变慢，不是数据竞争。</p><footer>—— 据 Bolosky and Scott；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/directory-scalability">上一课</a> 与 <a href="/cs/mesi-protocol">MESI</a> 都按<strong>行</strong>维护副本。<a href="/cs/line-size-sector">行大小</a> 越大，两个无关字段同行的概率越高。本课不重做目录 ack。缺口是把**伪共享（false sharing）**从「协议正确但性能崩」讲清楚：诊断是行颠簸，修复是对齐与填充，不是加目录。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>stats[tid]++</code> 若 <code>stats</code> 是紧挨着的 4B 元素，核 0 与核 1 的计数器可能同行。每次 <code>++</code> 要 M，于是行在两核 L1 之间按 <a href="/cs/moesi-mesif">MOESI</a> 飞。没有数据竞争：算法正确。缺口不是 fence，而是<strong>共享粒度是行，不是 C 变量。</strong></p><p><span class="marginnote">真共享：同一地址被多核读写，语义就需要通信。伪共享：地址不同、行相同。填充到行对齐把它们拆开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>诊断：PMU 上 LLC 写回/Snoop 命中对某数据段异常高，而代码无锁。修复：按行对齐每个核的热写字段；或线程局部再归约。结构体末尾 pad 到 64B。分区无法消除：配额再公平，inv 仍然发生。</p>',8)),(e(),n(p,null,{default:o(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20V0%5B%22%E6%A0%B80%20%E5%86%99%20x%22%5D%20--%3E%20LINE%5B%22%E5%90%8C%E4%B8%80%20cache%20%E8%A1%8C%22%5D%0A%20%20V1%5B%22%E6%A0%B81%20%E5%86%99%20y%22%5D%20--%3E%20LINE%0A%20%20LINE%20--%3E%20INV%5B%22%E6%9D%A5%E5%9B%9E%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20PAD%5B%22x%E3%80%81y%20%E5%88%86%E5%88%B0%E4%B8%8D%E5%90%8C%E8%A1%8C%22%5D%20--%3E%20OK%5B%22%E5%90%84%E6%8C%81%20M%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CPI 的一致性项可以压过 DRAM：cache-to-cache 延迟虽低于内存，频率极高时核空等。与 <a href="/cs/store-set-predict">存储集</a> 无关：那是单核内 load/store 地址。伪共享是多核行所有权。压缩与扇区：扇区可以减少传输字节，但标签/目录仍可能按整行作废，假共享未必消失。</p><p>数组下标按 tid 紧挨递增是教科书陷阱；改成 <code>tid * (64/sizeof)</code> 或用 per-cpu 再归约。C++ 的 <code>alignas(64)</code> 只保证起始对齐，结构体后面的字段仍可能与别人同行。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把无锁算法的 ABA 当伪共享。也不把 OS 的 per-cpu 数据展开，只点名那是同一药方。下一课原子操作：真共享时硬件如何在行上做 RMW。</p><p>后课默认：无逻辑共享仍可能行共享。真共享的 <code>swap</code>/<code>cas</code> 要在 cache 协议上实现，不是只靠 ALU。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>伪共享是行粒度一致性对无关变量的惩罚；对齐/填充拆行。</li><li>协议无需修改，软件布局是主药。</li><li>原子 RMW 如何占住一行，是下一课。</li><li>出处：Bolosky and Scott；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const P=r(h,[["render",f]]);export{C as __pageData,P as default};
